import json,re,pathlib,collections,hashlib,sys
# Usage: python3 bench/summarize_native_catalog_sanity.py [results-directory] [sweep-binary]
base=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else 'docs/performance/20261021');binary=pathlib.Path(sys.argv[2]) if len(sys.argv)>2 else None;r=[json.loads(x) for x in (base/'native-catalog-sanity.jsonl').read_text().splitlines()];s=pathlib.Path('src/audio/fx/catalog.ts').read_text()
catalog=[{'id':m[0],'sourceIndex':int(m[1])} for m in re.findall(r'"id": "([^"]+)",\s*"displayName": "[^"]+",\s*"sourceIndex": (\d+)',s)]
covered={x['effect'].replace('filter.','').replace('_','-') for x in r};covered.add('delay') if 'fractional-delay' in covered else None;missing=[x for x in catalog if x['id'] not in covered]
p=base/'native-catalog-sanity-summary.json';a={};a.update(cells=len(r), effectCount=len({x['effect'] for x in r}), signalMap=['silence','impulse','stereo matched sine','L-only','R-only','asymmetric stereo'], parameterVectors=['defaults','all descriptor minima','all descriptor maxima'], catalogIdMapping='Hyphens/underscores normalized; filter. prefix removed; Browser delay corresponds to Native fractional_delay. Some Native sourceIndex values are intentionally unknown.', factoryCoverageFormula='52 factories × 2 sample rates × 3 parameter vectors × 6 signals = 1872',missingSourceCatalogEffects=missing,missingReason='BEAT SHIFT uses source-aware loop transport, not an insert processor factory; the generic factory sweep cannot activate it',parameterRejectionReason='FREEZE descriptor maximum mode=1 is outside its supported discrete values [0]; not a hardware limitation',gates=dict(collections.Counter(x['functionalGate'] for x in r)),nonfiniteFrames=sum(x['nonfiniteFrames'] for x in r),processingFaults=sum(x['processingFault'] for x in r),maximumObservedPeak=max(x['peak'] for x in r),sourceSha256=hashlib.sha256(pathlib.Path('native-mvp/engine-cpp/tests/native_catalog_sanity_sweep.cpp').read_bytes()).hexdigest(),binarySha256=hashlib.sha256(binary.read_bytes()).hexdigest() if binary else None,topPeakCases=sorted(r,key=lambda x:x['peak'],reverse=True)[:10],topAbsoluteDcCases=sorted(r,key=lambda x:abs(x['dc']),reverse=True)[:10],qualityGate='NOT_ESTABLISHED: finite processing is not a clipping, DC, listening or long-tail acceptance test',baselineBoundary='Only PREAMP production source changed, with exact baseline/final PCM probes; this broader sweep is final-only, not a full-catalog baseline/final audio comparison')
p.write_text(json.dumps(a,indent=2)+'\n');print('source catalog count',len(catalog),'missing',missing)
